def connection_exists(ssid: str) -> Optional[str]:
    """ Check if a connection with the given SSID exists.

    Returns the nmcli connection name if it exists, None otherwise.
    """
    try:
        output = subprocess.check_output(
            ["nmcli", "connection", "show", "--active", "--all", "--no-pager"]
        )
    except subprocess.CalledProcessError as e:
        return None
    for line in output.decode().splitlines():
        if line.startswith(ssid):
            return line.split()[0]
    return None


def connection_exists_by_name(name: str) -> bool:
    """ Check if a connection with the given name exists.

    Returns True if it exists, False otherwise.
    """
    try:
        output = subprocess.check_output(
            ["nmcli", "connection", "show", "--active", "--all", "--no-pager"]
        )
    except subprocess.CalledProcessError as e:
        return False
    for line in output.decode().splitlines():
        if line.startswith(name):
            return True
    return False


